// Generates lib/geo/worldDots.ts — a compact land/sea bitmask used by the
// World Clock "map" style to draw a dotted world map without shipping any
// GeoJSON at runtime.
//
// The generated file is committed, so this only needs re-running to change
// the resolution or crop. Its dependencies aren't project deps on purpose:
//
//   npm i --no-save d3-geo world-atlas topojson-client
//   node scripts/generate-world-dots.mjs

import { writeFileSync } from 'node:fs'
import { createRequire } from 'node:module'
import { geoContains } from 'd3-geo'
import { feature } from 'topojson-client'

const require = createRequire(import.meta.url)
const topology = require('world-atlas/land-50m.json')
const land = feature(topology, topology.objects.land)

const STEP = 2.5 // degrees between dots
const LAT_TOP = 82.5
const LAT_BOTTOM = -57.5
const LON_LEFT = -180

const cols = Math.round(360 / STEP)
const rows = Math.round((LAT_TOP - LAT_BOTTOM) / STEP) + 1

const lines = []
for (let r = 0; r < rows; r++) {
  const lat = LAT_TOP - r * STEP
  let bits = ''
  for (let c = 0; c < cols; c++) {
    const lon = LON_LEFT + STEP / 2 + c * STEP
    bits += geoContains(land, [lon, lat]) ? '1' : '0'
  }
  // Pack 4 bits per hex char to keep the file small.
  let hex = ''
  for (let i = 0; i < bits.length; i += 4) {
    hex += parseInt(bits.slice(i, i + 4).padEnd(4, '0'), 2).toString(16)
  }
  lines.push(hex)
}

const out = `// Generated by scripts/generate-world-dots.mjs — do not edit by hand.
// Equirectangular land mask: one hex string per row (4 cells per char),
// rows from LAT_TOP down to LAT_BOTTOM, columns from -180° eastwards.

export const WORLD_DOTS = {
  step: ${STEP},
  latTop: ${LAT_TOP},
  latBottom: ${LAT_BOTTOM},
  lonLeft: ${LON_LEFT},
  cols: ${cols},
  rows: [
${lines.map((line) => `    '${line}',`).join('\n')}
  ],
} as const
`

writeFileSync(new URL('../lib/geo/worldDots.ts', import.meta.url), out)
console.log(`Wrote ${rows}x${cols} mask`)
